// Organic O — Framer code component
// BUILD: CLEAN-14 · direct production repair
// A WebGL "O" as a background whose shape, material AND camera angle morph
// from preset A -> preset B as the visitor scrolls between two sections.
//
//   - Self-contained: the whole shader is embedded (base64) in this file, so
//     there is nothing to host and no external URL to break.
//   - Renders at 1x (one shader pixel per CSS pixel) and PAUSES offscreen, so it stays
//     light even with several breakpoints on the Framer canvas.
//   - Non-interactive by default; flip "Interactive" on to let visitors orbit.
//
// SET YOUR LOOKS: paste your t1 into "Preset A JSON" and t2 into "Preset B
// JSON" (these win over the name fields). Built-in names also work:
// "trial 6", "transparent", "reference", "lava", "ghost".

import { useRef, useEffect, useCallback, useState } from "react"
import { addPropertyControls, ControlType } from "framer"
import { useScroll, useMotionValueEvent } from "framer-motion"

const PAGE_B64 = ""
/* atob yields one char per BYTE, so UTF-8 text (em dashes, middots, the
   preset labels) arrives mojibaked unless it is decoded as UTF-8. */
const RAW =
    typeof atob !== "undefined"
        ? new TextDecoder("utf-8").decode(
              Uint8Array.from(atob(PAGE_B64), (c) => c.charCodeAt(0))
          )
        : ""
// srcDoc has no URL to carry ?embed=1, so switch on background mode via a flag
const PAGE_HTML = RAW.replace("<head>", "<head><script>window.__ORGANIC_EMBED__=true;<\/script>")
const PAGE_HTML_T = RAW.replace("<head>", "<head><script>window.__ORGANIC_EMBED__=true;window.__ORGANIC_TRANSPARENT__=true;<\/script>")
const BUILD = { id: "CLEAN-14", commit: "local-clean14", sha: "clean14" }
const TSX_BUILD = "FIX-14"
const RENDERERS = { "Legacy EXIT-12": 0, "Clean Production": 1, "Difference": 2 }
/* Coverage diagnostics, addressable from the Framer panel. alphaDebug is a
   separate shader path, so "Alpha" maps to it rather than to a debug id. */
const DIAG = {
    "Final": { debugView: 0, alphaDebug: false },
    "Alpha": { debugView: 0, alphaDebug: true },
    "Binary Hit": { debugView: 25, alphaDebug: false },
    "Fractional AA": { debugView: 26, alphaDebug: false },
    "Budget Exhausted": { debugView: 27, alphaDebug: false },
    "Proof 1 · regular crossing": { debugView: 32, alphaDebug: false },
    "Proof 2 · near-eps verified": { debugView: 33, alphaDebug: false },
    "Proof 3 · late verified": { debugView: 34, alphaDebug: false },
    "Front T continuity": { debugView: 35, alphaDebug: false },
    "Surface residual ERROR": { debugView: 36, alphaDebug: false },
    "Exit bracket ERROR": { debugView: 37, alphaDebug: false },
    "Exit residual ERROR": { debugView: 38, alphaDebug: false },
    "Exit proof class": { debugView: 39, alphaDebug: false },
    "Exit T continuity": { debugView: 40, alphaDebug: false },
    "Front Normal": { debugView: 9, alphaDebug: false },
    "Chord Length L": { debugView: 8, alphaDebug: false },
    "Integrated OD": { debugView: 20, alphaDebug: false },
    "Pre-tone-map": { debugView: 21, alphaDebug: false },
    "CLEAN · invalid-number mask": { debugView: 41, alphaDebug: false },
    "CLEAN · surface normal": { debugView: 42, alphaDebug: false },
    "CLEAN · optical thickness": { debugView: 43, alphaDebug: false },
    "CLEAN · pre-tone-map": { debugView: 44, alphaDebug: false },
    "Old Rescue Candidates": { debugView: 28, alphaDebug: false },
    "Near-Epsilon Rejected": { debugView: 30, alphaDebug: false },
    "Candidate Band": { debugView: 31, alphaDebug: false },
    "Unproven Hit ERROR": { debugView: 29, alphaDebug: false },
    "Front-march Miss Reason": { debugView: 24, alphaDebug: false },
}
console.log("Organic O TSX BUILD " + TSX_BUILD, BUILD)

// Your dialed-in looks, baked in as the default A -> B journey:
//   t1: zoomed-in, frosted, inky, front-facing
//   t2: zoomed-out, transparent, ink drained, rotated ~146deg
const BUILT_IN = {
    t1: {"dials": {"debug": 0, "iso": 0, "ink": 0.95, "gravity": 0.82, "crange": 0.6, "light": 0.9, "glare": 0.85, "speed": 3.65, "fluid": 0.74, "fcenter": 0.19, "fthick": 0.47, "fdepth": 0.235, "flag": 0.35, "fsmooth": 0.72, "spin": 0.16, "tilt": 0.45, "tiltspd": 1, "wob": 0.45, "wobspd": 0.5, "morph": 0.79, "morphspd": 1.89, "ring": 0.71, "lobe": 0.17, "stretch": 0.14, "tube": 0.175, "flat": 0.7, "taper": 0.28, "zoom": 3.49, "frost": 0.18, "wall": 0.2, "speckle": 0, "soft": 0.9, "grain": 0, "bg": 0.955, "optv1": 1, "refrfull": 1, "exposure": 1.15, "rolloff": 0.85, "lift": 0.015, "shellth": 0.16, "shellcl": 0.7, "coresoft": 0.18, "fresstr": 1, "fresf0": 0.04, "reflstr": 1, "studiorot": 0.5, "stripw": 0.22, "strips": 0.16, "curvresp": 0.6, "hiwidth": 0.09, "hiint": 1, "ior": 1.45, "refrstr": 0.7, "disp": 0.012}, "view": {"yaw": 0, "pitch": 0}, "blobs": [{"color": "#101c33", "size": 0.55, "speed": 0.32, "amt": 1, "tail": 0.6, "drift": 0.45, "follow": false}, {"color": "#386bbc", "size": 0.85, "speed": -0.15, "amt": 0.4, "tail": 0.5, "drift": 0.7, "follow": false}]},
    t2: {"dials": {"debug": 0, "iso": 0, "ink": 0.95, "gravity": 0.82, "crange": 0.6, "light": 0.9, "glare": 0.85, "speed": 3.65, "fluid": 0.74, "fcenter": 0.19, "fthick": 0.47, "fdepth": 0.235, "flag": 0.35, "fsmooth": 0.72, "spin": 0.16, "tilt": 0.45, "tiltspd": 1, "wob": 0.64, "wobspd": 0.65, "morph": 0.84, "morphspd": 0.4, "ring": 0.71, "lobe": 0.17, "stretch": 0.14, "tube": 0.175, "flat": 0.7, "taper": 0.19, "zoom": 0.5, "frost": 0, "wall": 0.2, "speckle": 0, "soft": 0.9, "grain": 0, "bg": 0.955, "optv1": 1, "refrfull": 1, "exposure": 1.15, "rolloff": 0.85, "lift": 0.015, "shellth": 0.16, "shellcl": 0.7, "coresoft": 0.18, "fresstr": 1, "fresf0": 0.04, "reflstr": 1, "studiorot": 0.5, "stripw": 0.22, "strips": 0.16, "curvresp": 0.6, "hiwidth": 0.09, "hiint": 1, "ior": 1.45, "refrstr": 0.7, "disp": 0.012}, "view": {"yaw": 2.54591796875, "pitch": 0.0007421874999999742}, "blobs": [{"color": "#101c33", "size": 0.15, "speed": 0.35, "amt": 0, "tail": 0.6, "drift": 0.45, "follow": false}, {"color": "#386bbc", "size": 0.15, "speed": -0.15, "amt": 0, "tail": 0.5, "drift": 0.7, "follow": false}]},
}

const clamp = (v, a, b) => Math.max(a, Math.min(b, v))
function parseJSON(s) {
    if (!s) return null
    try {
        const o = JSON.parse(s)
        return o && o.dials && o.blobs ? o : null
    } catch {
        return null
    }
}

/* Reports the real pixel mapping: a fractional parent transform, or a canvas
   that is not 1:1 with its CSS box, resamples the render and can smear
   one-pixel features into visible tracks no shader change can fix. */
function PixelHud({ frameRef, quality }) {
    const [info, setInfo] = useState(null)
    useEffect(() => {
        let timer = 0
        const read = () => {
            const el = frameRef.current
            if (el) {
                const r = el.getBoundingClientRect()
                const cs = getComputedStyle(el)
                let cw = null, ch = null, iw = null, ih = null
                try {
                    const win = el.contentWindow
                    const cv = win && win.document.querySelector("canvas")
                    if (cv) { cw = cv.width; ch = cv.height }
                    if (win) { iw = win.innerWidth; ih = win.innerHeight }
                } catch (e) {}
                // every ancestor carrying a transform, not just the parent
                const chain = []
                let node = el.parentElement, depth = 0
                while (node && depth < 40) {
                    const t = getComputedStyle(node).transform
                    if (t && t !== "none") {
                        chain.push((node.tagName.toLowerCase()) +
                            (node.className && typeof node.className === "string"
                                ? "." + node.className.split(" ")[0] : "") + " " + t)
                    }
                    node = node.parentElement; depth++
                }
                const cssW = parseFloat(cs.width) || 0
                setInfo({
                    cssBox: [Math.round(cssW), Math.round(parseFloat(cs.height) || 0)],
                    rect: [Math.round(r.width), Math.round(r.height)],
                    iframeInner: [iw, ih],
                    canvas: [cw, ch],
                    ratioCss: cw && cssW ? +(cw / cssW).toFixed(3) : null,
                    ratioRect: cw && r.width ? +(cw / r.width).toFixed(3) : null,
                    dprRequested: quality,
                    devicePixelRatio: window.devicePixelRatio,
                    zoomHeuristic: +(window.outerWidth / window.innerWidth).toFixed(3),
                    childDpr: (() => { try { return el.contentWindow.devicePixelRatio } catch (e) { return null } })(),
                    selfTransform: cs.transform,
                    ancestors: chain,
                })
            }
            timer = setTimeout(read, 500)
        }
        read()
        return () => clearTimeout(timer)
    }, [frameRef, quality])
    if (!info) return null
    const scaled = info.ratioRect !== null && Math.abs(info.ratioRect - quality) > 0.02
    const anyXform = info.ancestors.length > 0 || info.selfTransform !== "none"
    const bad = scaled || anyXform
    return (
        <div style={{
            position: "absolute", right: 8, top: 8, zIndex: 2147483647,
            pointerEvents: "none", background: bad ? "#b4004e" : "#0a7",
            color: "#fff", font: "11px/1.5 ui-monospace, Menlo, monospace",
            padding: "6px 8px", borderRadius: 3, whiteSpace: "pre", textAlign: "left",
            maxWidth: 460, overflow: "hidden",
        }}>
{`css box       ${info.cssBox[0]} x ${info.cssBox[1]}
bounding rect ${info.rect[0]} x ${info.rect[1]}
iframe inner  ${info.iframeInner[0]} x ${info.iframeInner[1]}
canvas px     ${info.canvas[0]} x ${info.canvas[1]}
canvas/cssBox ${info.ratioCss}   (want ${quality})
canvas/rect   ${info.ratioRect}   (want ${quality})
parent DPR    ${info.devicePixelRatio}\nchild DPR     ${info.childDpr}\nzoom (heuristic, unreliable) ~${info.zoomHeuristic}
iframe xform  ${info.selfTransform}
ancestors with transform: ${info.ancestors.length}
${info.ancestors.slice(0, 5).join("\n") || "  (none)"}`}
        </div>
    )
}

export default function OrganicO(props) {
    /* Default parameters, not defaultProps: React 18.3 warns on defaultProps
       for function components and React 19 drops it. Framer reads the
       property-control defaults for the panel; these keep the component
       correct when it is rendered without a panel (previews, tests). */
    const {
        presetAName = "t1", presetBName = "t2",
        presetAJson = "", presetBJson = "",
        interactive = false, scrollStart = 0, scrollEnd = 1, quality = 1,
        transparentBg = true, alphaDebug = false,
        buildBadge = true, zoomMul = 1,
        renderer = "Clean Production",
        coverageDiag = "Final", freezeFrame = false, coverageAA = true,
        pixelHud = false, rawCapture = false, style,
    } = props

    const ref = useRef(null)
    const { scrollYProgress } = useScroll()

    /* Framer's String controls hand back "" (not undefined) when empty, so a
       default PARAMETER never fires for them. Resolving to "" used to send
       empty names, which the page ignored — it then kept its own built-ins
       ("trial 6" -> "transparent") and the scroll ran the wrong journey
       entirely. Always resolve to a real preset object. */
    const resolvePreset = (json, name, fallback) => {
        const parsed = parseJSON(json)
        if (parsed) return parsed
        const key = typeof name === "string" ? name.trim() : ""
        if (key && BUILT_IN[key]) return BUILT_IN[key]
        if (key) return key                 // a page built-in name, e.g. "lava"
        return fallback                     // empty -> the baked-in default
    }
    const A = resolvePreset(presetAJson, presetAName, BUILT_IN.t1)
    const B = resolvePreset(presetBJson, presetBName, BUILT_IN.t2)

    const post = useCallback((msg) => {
        ref.current?.contentWindow?.postMessage({ type: "organicO", ...msg }, "*")
    }, [])

    /* srcDoc is fixed for the component's lifetime. Deriving it from a live
       prop would swap the document on every toggle, tearing down the WebGL
       context and recompiling the shader; transparency changes travel by
       postMessage instead, so exactly ONE context and ONE RAF loop exist
       from mount to unmount. */
    const initialSrcDoc = useRef(transparentBg ? PAGE_HTML_T : PAGE_HTML)

    const sendConfig = useCallback(() => {
        const d = DIAG[coverageDiag] || DIAG.Final
        post({ a: A, b: B, interactive, dpr: quality, transparent: transparentBg,
               alphaDebug: alphaDebug || d.alphaDebug, debugView: d.debugView,
               freeze: freezeFrame, coverAA: coverageAA, rawCapture,
               renderer: RENDERERS[renderer] ?? 1,
               badge: buildBadge, zoomMul })
    }, [post, JSON.stringify(A), JSON.stringify(B), interactive, quality, transparentBg,
        alphaDebug, buildBadge, zoomMul, coverageDiag, freezeFrame, coverageAA, rawCapture, renderer])

    useEffect(() => { sendConfig() }, [sendConfig])
    useEffect(() => { console.log("Organic O TSX BUILD " + TSX_BUILD + " mounted", BUILD) }, [])

    // coalesce progress to at most one message per animation frame
    const pending = useRef(null)
    const raf = useRef(0)
    useMotionValueEvent(scrollYProgress, "change", (v) => {
        pending.current = clamp(
            (v - scrollStart) / Math.max(1e-6, scrollEnd - scrollStart), 0, 1
        )
        if (!raf.current) {
            raf.current = requestAnimationFrame(() => {
                raf.current = 0
                if (pending.current != null) post({ progress: pending.current })
            })
        }
    })
    // cancel the pending frame on unmount so no callback fires into a dead iframe
    useEffect(() => () => { if (raf.current) cancelAnimationFrame(raf.current) }, [])

    // pause GPU work while the O is out of view (and on inactive breakpoints)
    useEffect(() => {
        const el = ref.current
        if (!el || typeof IntersectionObserver === "undefined") return
        const io = new IntersectionObserver(
            ([e]) => post({ paused: !e.isIntersecting }),
            { rootMargin: "120px" }
        )
        io.observe(el)
        return () => io.disconnect()
    }, [post])

    /* Shadow suppression is UNCONDITIONAL, not a diagnostic toggle. Applied
       after ...style so a Framer layer effect (which lands there as boxShadow
       or filter: drop-shadow) cannot reintroduce one. */
    const noShadow = {
        boxShadow: "none", filter: "none",
        WebkitFilter: "none", backdropFilter: "none",
    }

    return (
        <div style={{ position: "relative", width: "100%", height: "100%", ...style, ...noShadow }}>
            <iframe
                ref={ref}
                srcDoc={initialSrcDoc.current}
                allowtransparency="true"
                onLoad={sendConfig}
                title="Organic O"
                style={{
                    width: "100%",
                    height: "100%",
                    border: "none",
                    background: "transparent",
                    colorScheme: "normal",
                    display: "block",
                    pointerEvents: interactive ? "auto" : "none",
                    ...noShadow,
                }}
            />
            {pixelHud && <PixelHud frameRef={ref} quality={quality} />}
            {buildBadge && (
                <div
                    style={{
                        position: "absolute", left: 8, top: 8, zIndex: 2147483647,
                        pointerEvents: "none", background: "#b4004e", color: "#fff",
                        font: "11px/1.45 ui-monospace, SFMono-Regular, Menlo, monospace",
                        padding: "4px 8px", borderRadius: 3, whiteSpace: "pre",
                        boxShadow: "none",
                    }}
                >
                    {"TSX BUILD: " + TSX_BUILD + " · page " + BUILD.id + " · " + BUILD.sha}
                </div>
            )}
        </div>
    )
}

addPropertyControls(OrganicO, {
    presetAName: { type: ControlType.String, title: "Preset A", placeholder: "t1 (built-in)" },
    presetBName: { type: ControlType.String, title: "Preset B", placeholder: "t2 (built-in)" },
    presetAJson: { type: ControlType.String, title: "Preset A JSON", displayTextArea: true, placeholder: "(optional) paste t1 JSON" },
    presetBJson: { type: ControlType.String, title: "Preset B JSON", displayTextArea: true, placeholder: "(optional) paste t2 JSON" },
    interactive: { type: ControlType.Boolean, title: "Interactive", defaultValue: false, enabledTitle: "On", disabledTitle: "Off" },
    scrollStart: { type: ControlType.Number, title: "Scroll start", min: 0, max: 1, step: 0.01, defaultValue: 0 },
    scrollEnd: { type: ControlType.Number, title: "Scroll end", min: 0, max: 1, step: 0.01, defaultValue: 1 },
    quality: { type: ControlType.Number, title: "Quality (DPR)", min: 1, max: 2, step: 0.25, defaultValue: 1, description: "1 = one shader pixel per CSS pixel (production). 2 = development/high-quality only." },
    zoomMul: { type: ControlType.Number, title: "Scale", min: 0.2, max: 5, step: 0.05, defaultValue: 1, description: "Multiplies the preset zoom. Apparent size follows the container HEIGHT." },
    transparentBg: { type: ControlType.Boolean, title: "Transparent BG", defaultValue: true, enabledTitle: "On", disabledTitle: "Off", description: "Off = the shader paints its own studio backdrop." },
    renderer: { type: ControlType.Enum, title: "Renderer", defaultValue: "Clean Production",
        options: ["Clean Production", "Legacy EXIT-12", "Difference"],
        description: "Clean Production is the rebuilt deterministic path. Difference shows |clean - legacy| amplified 8x on identical geometry." },
    coverageDiag: { type: ControlType.Enum, title: "Coverage Diagnostic", defaultValue: "Final",
        options: ["Final","Alpha","Binary Hit","Fractional AA","Budget Exhausted","Proof 1 · regular crossing","Proof 2 · near-eps verified","Proof 3 · late verified","Front T continuity","Surface residual ERROR","Exit bracket ERROR","Exit residual ERROR","Exit proof class","Exit T continuity","Front Normal","Chord Length L","Integrated OD","Pre-tone-map","CLEAN · invalid-number mask","CLEAN · surface normal","CLEAN · optical thickness","CLEAN · pre-tone-map","Old Rescue Candidates","Near-Epsilon Rejected","Candidate Band","Unproven Hit ERROR","Front-march Miss Reason"],
        description: "Diagnostic only. Unproven Hit ERROR must render completely black." },
    freezeFrame: { type: ControlType.Boolean, title: "Freeze", defaultValue: false, enabledTitle: "On", disabledTitle: "Off", description: "Halts the animation so two diagnostics compare the same frame." },
    coverageAA: { type: ControlType.Boolean, title: "Coverage AA", defaultValue: true, enabledTitle: "On", disabledTitle: "Off", description: "Subpixel silhouette coverage. Turn off to isolate binary hit correctness." },
    rawCapture: { type: ControlType.Boolean, title: "RAW FRAME CAPTURE", defaultValue: false, enabledTitle: "Grab", disabledTitle: "Off", description: "Reads the drawing buffer directly and shows it 1:1 with no CSS scaling. Clean here + lines on screen = a compositing problem, not the shader." },
    pixelHud: { type: ControlType.Boolean, title: "Pixel mapping HUD", defaultValue: false, enabledTitle: "Show", disabledTitle: "Hide", description: "Reports canvas vs CSS pixels, DPR and any parent transform scaling." },
    alphaDebug: { type: ControlType.Boolean, title: "Alpha debug", defaultValue: false, enabledTitle: "On", disabledTitle: "Off", description: "Diagnostic: black = alpha 0, white = alpha 1." },
    buildBadge: { type: ControlType.Boolean, title: "Build badge", defaultValue: true, enabledTitle: "Show", disabledTitle: "Hide", description: "Shows BUILD id / commit / sha in the corner. Turn off before publishing." },
})
